`timescale 1ns/1ps
// Generated by spice2rnm board mode (bench) from bms_6s_fab.cir.
// Every connection below comes from the schematic, the part library,
// the MCU pad map or the scenario; none is written by hand.
module bench_top;

  // ---- analog nets
  wreal n_P3V3, n_B1, n_B2, n_B3, n_B4, n_B5;
  wreal n_B6, n_BATRC, n_CHG, n_CHG_G, n_DSG, n_DSG_G;
  wreal n_FETMID, n_LED, n_LEDK, n_PACK_M, n_REGSRC, n_SCL;
  wreal n_SDA, n_SRB, n_SRN, n_SRN_K, n_SRP, n_SRP_K;
  wreal n_VC0F, n_VC1F, n_VC2F, n_VC3F, n_VC5BF, n_VC6F;
  wreal n_VC7F, n_VC8F;
  // ---- logic nets, open-drain pulls, switch states
  logic l_ALERT, l_SCL, l_SDA, dr_SCL_U2, od_SDA_U1, od_SDA_U2;
  logic on_Q1, on_Q2;

  // ---- scenario
  real i_cmd_J2 = 1.0;
  initial begin
    #15000000;
    i_cmd_J2 = 4.2;
    $display("[scenario] t=%0t: load raised to 4.2 A (overload)", $time);
    #25000000;
    i_cmd_J2 = 0.5;
    $display("[scenario] t=%0t: load reduced to 0.5 A", $time);
  end

  // ---- current path
  real i_path;
  assign i_path = (on_Q1) ? i_cmd_J2 : 0.0;
  assign n_SRB = i_path * 0.001;  // /SRB
  assign n_FETMID = (on_Q1) ? i_path * 0.001 : n_B6;  // /FETMID
  assign n_PACK_M = (on_Q1) ? i_path * 0.001 : n_B6;  // /PACK_M

  // ---- passive networks (board mode, verified against ngspice)
  bms_6s_fab_passives u_passives (
    .P3V3(n_P3V3),
    .SCL(n_SCL),
    .SDA(n_SDA),
    .CHG(n_CHG),
    .PACK_M(n_PACK_M),
    .CHG_G(n_CHG_G),
    .LEDK(n_LEDK),
    .LED(n_LED),
    .SRB(n_SRB),
    .SRN(n_SRN),
    .SRN_K(n_SRN_K),
    .SRP(n_SRP),
    .SRP_K(n_SRP_K),
    .DSG(n_DSG),
    .DSG_G(n_DSG_G),
    .B1(n_B1),
    .B2(n_B2),
    .B3(n_B3),
    .VC0F(n_VC0F),
    .VC1F(n_VC1F),
    .VC2F(n_VC2F),
    .VC3F(n_VC3F),
    .B4(n_B4),
    .B5(n_B5),
    .B6(n_B6),
    .VC5BF(n_VC5BF),
    .VC6F(n_VC6F),
    .VC7F(n_VC7F),
    .VC8F(n_VC8F),
    .REGSRC(n_REGSRC),
    .BATRC(n_BATRC)
  );

  // ---- parts
  // Q2 (NFET40)
  part_nfet_switch #(.VTO(2.0)) u_Q2 (
    .g(n_CHG_G),
    .s(n_PACK_M),
    .on(on_Q2)
  );
  // Q1 (NFET40)
  part_nfet_switch #(.VTO(2.0)) u_Q1 (
    .g(n_DSG_G),
    .s(n_SRB),
    .on(on_Q1)
  );
  // J1 (PACK6S)
  part_pack6s #(.OCV(3.7), .RINT(0.012)) u_J1 (
    .n1(n_B1),
    .n2(n_B2),
    .n3(n_B3),
    .n4(n_B4),
    .n5(n_B5),
    .n6(n_B6),
    .i_pack(i_path)
  );
  // U1 (BQ76930_BEH)
  part_bq76930_6s #(.TEMP_C(25.0)) u_U1 (
    .vc0(n_VC0F),
    .vc1(n_VC1F),
    .vc2(n_VC2F),
    .vc3(n_VC3F),
    .vc5b(n_VC5BF),
    .vc6(n_VC6F),
    .vc7(n_VC7F),
    .vc8(n_VC8F),
    .srp(n_SRP),
    .srn(n_SRN),
    .dsg(n_DSG),
    .chg(n_CHG),
    .regout(n_P3V3),
    .scl(l_SCL),
    .sda_pull(od_SDA_U1),
    .sda_bus(l_SDA),
    .alert(l_ALERT)
  );
  // U2, the MCU, through the emulator bridge
  renode_bridge2 #(.PORT(43602)) u_U2 (
    .scl(dr_SCL_U2),
    .sda_pull(od_SDA_U2),
    .sda_bus(l_SDA),
    .alert(l_ALERT)
  );

  // ---- net resolution
  assign n_LEDK = 0.0;  // nothing on the board drives /LEDK
  assign l_SCL = !(!dr_SCL_U2) && (n_SCL > 2.31);
  assign l_SDA = !(od_SDA_U1 || od_SDA_U2) && (n_SDA > 2.31);

endmodule : bench_top
